/* Types */
/**
 *  Who the person is, as the accounts server describes them.
 * 
 *  Two fields today, because two are what the server has. The shape is an
 *  object rather than a bare string so a handle, an avatar and a plan can
 *  arrive later without every caller changing.
 */
export type Account = {
	id: string,
	email: string,
	/**
	 *  What the person calls themselves, when they have set one. Absent rather
	 *  than derived from the address: a name nobody chose is worse than none.
	 */
	name: string | null,
	/**  RFC 3339, in UTC. */
	createdAt: string,
};

/**  What an agent asked a page to do. */
export type Act = 
/**  Put text into the element a selector names. */
{ act: "type"; selector: string; text: string } | 
/**  Click the element a selector names. */
{ act: "click"; selector: string } | 
/**  Scroll the page by a number of viewport heights. */
{ act: "scroll"; by: number | null };

/**  An agent on this machine, as the step picker needs it. */
export type Agent = {
	/**  The name in the file's frontmatter — what a step stores. */
	name: string,
	description: string,
	model: string | null,
	/**
	 *  Where it came from — `omc`, `claude`, `yours`. Shown beside the name so
	 *  two agents that share one can be told apart.
	 */
	source: string,
};

export type AgentChoice = {
	/**
	 *  What a new terminal opens, by agent or profile id. Empty for none,
	 *  which is a plain shell — a deliberate answer, not a missing one.
	 */
	defaultId: string,
	/**  Ids kept out of the menus. Off the catalogue, not uninstalled. */
	disabled: string[],
	/**
	 *  Whether an agent devpit starts is told to report what it is doing.
	 * 
	 *  The hooks travel on the command line and reach only the agents this app
	 *  starts — nothing is written into anybody's own configuration, so
	 *  turning this off is the whole of turning it off.
	 */
	hooks: boolean,
};

/**  Who is running in the leaf. `none` is a plain shell. */
export type AgentPresence = "none";

/**
 *  Response of `agents.list`.
 * 
 *  The files that would not load come back too, by name. A step pointing at an
 *  agent that is silently missing fails at the moment it runs, which is the
 *  worst time to find out it was a typo.
 */
export type Agents = {
	agents: Agent[],
	rejected: RejectedAgent[],
	/**  Where they live, so the screen can say where to put another one. */
	directory: string,
};

/**  What a person answered. */
export type Answer = "allow" | 
/**
 *  Refused. The refusal goes back to the agent as a tool result rather
 *  than killing the turn — an agent told "no" can try something else.
 */
"deny";

/**
 *  Response of `app.info`.
 * 
 *  An object, never a bare list — and that holds for every response in the
 *  contract. Tomorrow's extra field must not break today's consumer, and a
 *  bare list has nowhere to put it.
 */
export type AppInfo = {
	version: string,
	platform: string,
	/**
	 *  Where this build keeps state. Exposed on purpose: it is the first
	 *  question of anyone taking a backup or filing a bug.
	 */
	statePath: string,
	/**
	 *  Whether this is a devpit being worked on rather than the installed one.
	 *  A debug build keeps a home of its own, and the window says so on its
	 *  face: two devpits open side by side look identical otherwise, and the
	 *  one you are testing in is not the one holding your real work.
	 */
	dev: boolean,
};

/**  A card off the board, as the Archived list shows it. */
export type ArchivedCard = {
	id: string,
	title: string,
	columnName: string | null,
	archivedAt: number | null,
};

/**  Response of `board.archived`: most recently archived first, at most 200. */
export type ArchivedCards = {
	cards: ArchivedCard[],
};

/**
 *  What one turn needs to run. One object because the composer sends these
 *  together, and because tomorrow's field needs somewhere to live.
 */
export type Ask = {
	projectId: string,
	conversationId: string,
	/**  Which profile — the account, and the binary it names. */
	profileId: string,
	model: string | null,
	prompt: string,
	cwd: string,
	/**  A ceiling for the whole conversation, not for this turn. */
	budgetUsd: number | null,
	/**
	 *  What the agent may do without asking, in the CLI's own words.
	 *  Absent keeps whatever the conversation already had.
	 */
	permission: string | null,
	/**  How hard to think. Absent keeps what the conversation already had. */
	effort: string | null,
};

/**
 *  A file the person put in front of the agent.
 * 
 *  The path is relative to the project root, because that is the only form
 *  the agent can use and the only form that survives another machine.
 */
export type Attachment = {
	name: string,
	path: string,
	/**  The extension, lowercased, or empty. What the chip draws. */
	kind: string,
};

/**  A block that started or ended, in the pane it belongs to. */
export type BlockChanged = {
	paneId: string,
	block: CommandBlock,
};

/**
 *  Response of `board.get`.
 * 
 *  An object rather than a bare list of columns: the board will grow a field,
 *  and a bare list has nowhere to put it.
 */
export type Board = {
	projectId: string,
	columns: Column[],
	cards: Card[],
	steps: Step[],
};

export type Branch = {
	name: string,
	current: boolean,
	/**
	 *  The subject of its last commit, so a name nobody remembers still says
	 *  what it is.
	 */
	subject: string,
};

export type Branches = {
	branches: Branch[],
};

/**  How a tool call ended, or that it has not. */
export type CallState = "running" | "ok" | "failed";

export type Card = {
	id: string,
	columnId: string,
	title: string,
	body: string,
	position: number,
	worktreePath: string | null,
	/**
	 *  Seconds since the epoch; `f64` for the usual reason. Absent for most
	 *  cards, which is why it is an option and not a date nobody chose.
	 */
	dueAt: number | null,
	/**  What every run of this card has cost, added up. */
	costUsd: number | null,
	/**
	 *  Counted, not carried: the tile shows that there is a conversation, and
	 *  the conversation itself is read when the card is opened.
	 */
	comments: number,
	pinned: number,
	/**  Most recent first. */
	runs: Run[],
	/**
	 *  What the sessions working on this card add up to, the one most worth a
	 *  look. `None` when nothing is working on it.
	 */
	activity: Doing | null,
};

/**  Response of `card.create` and `card.move`. */
export type CardChanged = {
	card: Card,
	/**  The run this move started, when the column it landed in has a step. */
	started: Run | null,
};

/**
 *  Response of `card.delete`.
 * 
 *  A refusal is an answer rather than an error: the screen has to know whether
 *  asking again with `force` can change it.
 */
export type CardDeleted = {
	deleted: boolean,
	refused: DeleteRefusal | null,
};

/**  Everything one card is, for the screen that opens it. */
export type CardDetail = {
	card: Card,
	columnName: string,
	/**
	 *  What the lane this card is in runs, if anything. Here rather than
	 *  looked up by the screen: the card pane needs it to say what play does,
	 *  and a second read would be a second answer.
	 */
	columnStep: Step | null,
	comments: Comment[],
	pinned: Pinned[],
	/**  Absent until the card has one. */
	worktree: Checkout | null,
	/**  Every run, newest first — the tile only carries the latest. */
	runs: Run[],
	/**
	 *  Every session working on the card: its tab's panes, runs with a session,
	 *  its background session and its conversations.
	 */
	sessions: CardSession[],
};

/**  What `card:happening` carries: a card's sessions, and what they add up to. */
export type CardHappening = {
	cardId: string,
	/**  The one the tile shows. `None` once nothing is left. */
	activity: Doing | null,
	sessions: CardSession[],
};

/**  One session working on a card. */
export type CardSession = {
	kind: SessionKind,
	/**
	 *  A leaf for a pane, a session id for a run or a background session, a
	 *  conversation for a chat.
	 */
	ref: string,
	/**
	 *  `None` for a pane or a run whose agent has said nothing since the app
	 *  opened — it is listed, but nobody knows what it is doing.
	 */
	state: Doing | null,
	/**  Where a pane is, so the card can go to it. */
	tabId: string | null,
	leafId: string | null,
	/**  The run a `run` session belongs to, so the card can stop it. */
	runId: string | null,
};

/**
 *  Response of `card.terminal`: the layout, and the tab and card it belongs to.
 * 
 *  The window files the tab under these and never spells the tab's id itself:
 *  a second place writing the prefix is a second place to get it wrong.
 */
export type CardTerminal = {
	layout: SessionLayout,
	tabId: string,
	cardId: string,
};

/**  One checkout belonging to a card, or left over from one. */
export type CardWorktree = {
	/**  The card it belongs to, which is the folder's name. */
	cardId: string,
	/**  Present when a card by that id still exists. */
	cardTitle: string | null,
	folder: string,
	branch: string | null,
	/**
	 *  Bytes on disk. A feature that quietly eats forty gigabytes is a feature
	 *  people uninstall.
	 */
	diskBytes: number | null,
	uncommittedFiles: number,
	uncommittedLines: number,
	/**  True when the folder is there and the card is not. */
	orphan: boolean,
};

export type Change = {
	path: string,
	status: GitStatus,
	added: number,
	removed: number,
	/**  True when the change is in the index — what a commit would take. */
	staged: boolean,
};

/**  One file a turn changed, relative to the checkout it ran in. */
export type ChangedFile = {
	path: string,
	added: number,
	removed: number,
};

/**
 *  Everything the screen needs about one run, in one answer.
 * 
 *  The three states are separate fields and never one: a screen that had to
 *  derive `Verdict` from `RunState` would be the screen that draws exit code
 *  zero as a green tick.
 */
export type Checked = {
	runId: string,
	state: RunState,
	verdict: Verdict,
	validity: Validity,
	/**
	 *  What the run ran, or nothing for a row that never said. The screen
	 *  showing nothing here says "unknown", not a blank that reads like none.
	 */
	ran: WhatRan | null,
	/**
	 *  The evidence's shape, when a run left any. The payload itself is asked
	 *  for separately: a list of runs is not a place to send megabytes.
	 */
	evidenceVersion: number | null,
	/**
	 *  Who asked and what did the work. Two answers, because Claude can ask
	 *  for a test the local runner executes and Codex reviews.
	 */
	whose: Whose,
};

/**
 *  The checkout this card's work happens in.
 * 
 *  `Checkout` and not `CardWorktree`, which the settings pane already uses for
 *  its own row — that one is about disk and orphans, this one about the branch
 *  and what is uncommitted in it. Two views of one fact, and the names have to
 *  say which is which.
 */
export type Checkout = {
	path: string,
	branch: string | null,
	/**  What it started from. The diff is against this, never against HEAD. */
	baseRef: string | null,
	/**  Null when git could not be read — not 0, which would claim it is clean. */
	dirtyFiles: number | null,
	/**  False when the row names a folder that is no longer there. */
	exists: boolean,
};

export type ClaudePluginInstallation = {
	directory: string,
	profiles: string[],
	state: ClaudePluginState,
};

/**  Where the plugin stands in one installation. */
export type ClaudePluginState = "missing" | 
/**  Installed from an earlier build of the plugin. */
"outdated" | "current";

export type Column = {
	id: string,
	name: string,
	position: number,
	/**  `null` means the column runs nothing, which is a column doing its job. */
	step: Step | null,
	/**
	 *  Where a card goes when this lane's step approves it.
	 * 
	 *  Declared rather than derived: "the next column by position" is the
	 *  obvious rule and a trap, because a column is data — renamed, reordered
	 *  by dragging — so a card would start advancing somewhere else with
	 *  nobody having changed anything about it.
	 */
	onPass: string | null,
	/**
	 *  `manual` | `ask` | `auto`. How much this lane decides on its own.
	 * 
	 *  `manual` is the default and what every existing board has: nothing
	 *  happens without somebody moving a card.
	 */
	autonomy: string,
};

/**
 *  Response of `board.column_delete` when the column still holds cards.
 * 
 *  Refusing is the answer, but refusing without saying how many would leave
 *  the screen asking a question it cannot phrase.
 */
export type ColumnDeleted = {
	deleted: boolean,
	cardsInTheWay: number,
};

/**  One command a pane ran, or is running. */
export type CommandBlock = {
	/**
	 *  Rises with every block the pane has had, across restarts. `f64`
	 *  because it crosses into a JavaScript number.
	 */
	id: number | null,
	command: string | null,
	/**  Where it ran, when the shell said. */
	cwd: string | null,
	/**  Unix milliseconds. */
	startedAt: number | null,
	endedAt: number | null,
	/**  Absent while running, and for a command that ended without saying. */
	code: number | null,
	/**  It took the whole screen, so its output is drawing, not lines. */
	interactive: boolean,
	/**  Its output was too long, and the start of it was dropped. */
	truncated: boolean,
	/**  Marked by the person, to jump back to it. */
	bookmarked: boolean,
};

/**  One line of the card's conversation. */
export type Comment = {
	id: string,
	/**
	 *  `you`, or an agent id — never a display name. Names change, and the
	 *  screen resolves the id to whatever it calls that agent today.
	 */
	author: string,
	body: string,
	/**
	 *  Seconds since the epoch; `f64` because this crosses into a JavaScript
	 *  number. See `Commit::committed_at` for the reason stated once.
	 */
	createdAt: number | null,
	/**  Present when the line was changed after it was said. */
	editedAt: number | null,
};

export type Commit = {
	/**  Abbreviated, because that is what is read and quoted. */
	sha: string,
	subject: string,
	author: string,
	/**
	 *  Seconds since the epoch.
	 * 
	 *  `f64` and not `i64`, because this crosses into a JavaScript number and
	 *  that is what a JavaScript number is. An `f64` represents every whole
	 *  second exactly up to 2^53 of them — 285 million years — so nothing is
	 *  lost, and the type says so instead of leaving a 64-bit integer to be
	 *  silently truncated by `JSON.parse`.
	 * 
	 *  Formatting a duration stays the screen's job, in the reader's locale
	 *  and against the reader's clock.
	 */
	committedAt: number | null,
};

/**  A commit named in full, and its page on the remote's forge if it has one. */
export type CommitRef = {
	full: string,
	url: string | null,
};

/**
 *  How full the model's context was at the end of a turn, in tokens: what
 *  the last request carried, against the window it had. What a person needs
 *  to see before the CLI compacts — or refuses — on its own.
 */
export type Context = {
	used: number,
	window: number,
};

export type Conversation = {
	id: string,
	projectId: string,
	cardId: string | null,
	/**  That card's title, so the chat can name it. */
	cardTitle: string | null,
	/**  Whether that card is still on a board, which is when the chat can open it. */
	cardOnBoard: boolean,
	/**
	 *  The profile — account and driver — this conversation belongs to, for
	 *  its whole life.
	 * 
	 *  Fixed on purpose: the transcript, the shape of a message and the way
	 *  cost is counted all belong to one account. Changing it is starting
	 *  another conversation, not continuing this one.
	 */
	profile: string,
	/**  The model within that provider, which the composer may change. */
	model: string | null,
	/**
	 *  The permission mode and effort the last turn ran with, so reopening the
	 *  conversation does not quietly fall back to the most careful mode.
	 */
	permission?: string | null,
	effort?: string | null,
	/**  The folder its turns run in, which a relative link in an answer is read against. */
	cwd?: string | null,
	/**
	 *  The CLI's own id for this thread, once it has run a turn. It is what
	 *  ties a permission question back to the conversation that raised it.
	 */
	sessionId: string | null,
	messages: Message[],
	costUsd: number | null,
	/**  How full the context was when the last turn ended. */
	context?: Context | null,
	/**
	 *  The turns a rewind can fork at: those whose place in the CLI's
	 *  transcript was kept. Earlier turns ran before it was.
	 */
	rewindable?: string[],
	createdAt: number | null,
};

export type Conversations = {
	conversations: Thread[],
};

/**  What a plugin's data folder is allowed to hold. */
export type DataSpec = {
	/**  Each with its leading dot, e.g. `.excalidraw`. Enforced by [`validate`]. */
	extensions: string[],
	/**
	 *  Bytes; `f64` and not `u64` because this crosses into a JavaScript
	 *  number and specta refuses `u64` by default — see `Commit::committed_at`
	 *  for why `f64`.
	 */
	maxBytes: number | null,
};

/**
 *  A profile as the person wrote it.
 * 
 *  The shape was measured rather than invented. Five of these existed as shell
 *  functions in one `.zshrc` before devpit had anywhere to put them, and every
 *  one of them was the same three things:
 * 
 *  ```text
 *  glm()     = {seven ANTHROPIC_* vars} + claude + [--permission-mode bypassPermissions]
 *  claudin() = {CLAUDE_CONFIG_DIR}       + claude + [--permission-mode bypassPermissions]
 *  ```
 * 
 *  `glm` and `claudin` differ in **nothing but the environment**. So a profile
 *  is environment, program and arguments — not a command line. That matters
 *  twice: a command line would have to be handed to a shell, and a shell
 *  function cannot be spawned at all, which is why those five worked in a
 *  terminal and nowhere else devpit could reach.
 */
export type Declared = {
	/**
	 *  Minted once and never derived from the label, because the label is the
	 *  part the person is invited to change.
	 */
	id: string,
	/**  What they called it. */
	label: string,
	/**
	 *  The agent this behaves like, by `devpit_pty::agents` id. It carries the
	 *  driver, the hook flag and the default program.
	 */
	base: string,
	/**  The program to run. Empty means the base agent's own. */
	command?: string,
	args?: string[],
	env?: EnvVar[],
	/**
	 *  The models offered in place of the driver's. A gateway such as z.ai
	 *  serves none of Anthropic's, so its profile names its own. Empty keeps
	 *  the driver's list.
	 */
	models?: string[],
};

/**  Why a card was not deleted. */
export type DeleteRefusal = {
	reason: string,
	/**  True only for unsaved work, which is the person's to throw away. */
	forcible: boolean,
};

/**
 *  What somebody did in the menu, on its way back to the pane that owns it.
 * 
 *  The menu runs in another window, so it cannot reach the pane's React state.
 *  Commands that need no window — listing sessions, reading a store, granting
 *  — it calls itself; anything that changes what the *pane* shows comes back
 *  through here.
 */
export type Did = 
/**  Put the pane in this session, which reopens the page in it. */
{ did: "session"; session: string } | 
/**  Hold the page at this width, or at the pane's own when none. */
{ did: "viewport"; viewport: string | null } | 
/**  Whether an agent may drive this page. */
{ did: "grant"; granted: boolean } | 
/**  Something to tell the person, in the pane's own strip. */
{ did: "said"; said: string };

/**  What a session is doing, as its agent last said. */
export type Doing = 
/**  It began and has said nothing since. */
"open" | "working" | 
/**  Stopped on a person — the one worth coming back for. */
"waiting" | "done" | 
/**  Its run ended badly. */
"failed" | 
/**  It ended. */
"gone";

export type Drove = {
	pane: string,
	said: string,
};

/**
 *  One environment variable a profile sets before its program starts.
 * 
 *  A pair and not a `HashMap`, because order is what somebody typed and a map
 *  would reshuffle their list every time the pane redrew.
 */
export type EnvVar = {
	name: string,
	/**  Often a secret. Never logged, never put in an error message. */
	value: string,
};

export type ErrorCode = "unauthenticated" | 
/**
 *  Used when a path falls outside the registered project root. Distinct
 *  from a generic error on purpose: the daemon runs terminals and writes
 *  files, so reaching it is reaching the machine.
 */
"forbidden" | "not_found" | "conflict" | "rate_limited" | "invalid" | "unsupported" | "busy" | "internal";

/**  What the next error report would send, for the person to read first. */
export type ErrorReportsPreview = {
	/**  Errors kept and not yet reported. */
	waiting: number,
	/**  The next request's body, exactly as it would go. */
	next: string,
};

/**
 *  What is in a file, or why it is not shown.
 * 
 *  A binary file is refused rather than rendered: a megabyte of bytes drawn as
 *  replacement characters is worse than a sentence saying it is not text, and
 *  saving it back would corrupt it.
 */
export type FileContents = {
	/**  Relative to the worktree root, the same path the tree hands out. */
	path: string,
	text: string | null,
	/**  Set when `text` is absent, and it says which reason. */
	notShown: string | null,
	bytes: number | null,
	/**
	 *  The mtime the read saw, given back on write so a save can refuse to
	 *  overwrite a change it never saw.
	 */
	readAt: number | null,
	kind: FileKind,
	/**
	 *  The bytes, as a `data:` URL, for an image or a PDF small enough to
	 *  carry. Absent for everything else — text goes in `text`.
	 */
	dataUrl: string | null,
	/**  The absolute path, for revealing in the file manager. Never drawn. */
	fullPath: string,
};

export type FileIndex = {
	/**  Paths relative to the project root. */
	paths: string[],
	/**
	 *  True when the walk stopped at the ceiling. The screen says the list is
	 *  partial rather than letting a missing file read as "not there".
	 */
	partial: boolean,
};

/**  What a file is, so the screen knows what to draw rather than guessing. */
export type FileKind = "text" | "markdown" | "image" | "pdf" | 
/**  Nothing this window can draw. The screen says which type and how big. */
"binary";

/**
 *  One entry of the file tree.
 * 
 *  Children are `None` for a file and `Some` for a directory — including an
 *  empty `Some`, which is how an empty directory differs from a file.
 */
export type FileNode = {
	name: string,
	/**  Relative to the worktree root. What every other command takes back. */
	path: string,
	status: GitStatus,
	children: FileNode[] | null,
};

/**  The answer to a write. */
export type FileSaved = {
	path: string,
	bytes: number | null,
	readAt: number | null,
};

/**  One thing a review found. */
export type Finding = {
	/**  Relative to the checkout the review ran in. */
	file: string,
	/**
	 *  1-based, as an editor counts. `None` for a finding about the file
	 *  rather than a place in it.
	 */
	line: number | null,
	severity: Severity,
	/**
	 *  Why this is a finding. Empty is refused: a finding nobody can evaluate
	 *  is a claim, not a finding.
	 */
	why: string,
};

/**  A folder's git state, for a terminal's prompt chips. */
export type FolderGlance = {
	branch: string,
	files: number,
	added: number,
	removed: number,
};

/**
 *  A review as the screen reads it: what it found, and whether it still
 *  points where it says.
 */
export type Found = {
	findings: Finding[],
	standing: Standing,
	/**  The revision the review was made against. */
	atRevision: string | null,
	/**
	 *  The revision the code is at now. Both are shown when they differ: a
	 *  person reading an outdated review needs to know which two.
	 */
	now: string | null,
	rubric: string | null,
};

/**  What the stream carries, one frame at a time. */
export type Frame = 
/**  A message opened; parts follow. */
{ type: "opened"; message: Message } | 
/**  More of the message that is open. */
{ type: "part"; message_id: string; part: Part } | 
/**  A tool call moved on. */
{ type: "call_state"; call_id: string; state: CallState } | 
/**
 *  The CLI named its session. A new conversation learns it here, while
 *  the turn runs, rather than from the head written after it.
 */
{ type: "session"; session_id: string } | 
/**  The turn is over. Absence of frames is not an ending. */
{ type: "ended"; end: TurnEnd };

/**
 *  Response of `card.diff` — what this front changed, against where it began.
 * 
 *  `baseRef` travels with it so the screen can say what the diff is against.
 *  A diff with no stated base is a diff nobody can check.
 */
export type Front = {
	worktreePath: string | null,
	baseRef: string | null,
	files: string[],
	diff: string,
	/**
	 *  Work no commit holds. Named rather than counted, because the question
	 *  it answers is "what would I lose".
	 */
	unsaved: string[],
};

/**
 *  How a path stands with git.
 * 
 *  Deliberately smaller than git's own vocabulary: the screen draws a handful
 *  of colours, and a status the screen cannot draw is a status nobody asked
 *  for.
 */
export type GitStatus = "clean" | "modified" | "added" | "deleted" | "untracked" | 
/**  Matched by an ignore rule: not a change, a thing git is not watching. */
"ignored";

/**  The payload of `terminal:happening`. */
export type Happening = {
	paneId: string,
	/**
	 *  `cwd` | `title` | `prompt` | `running` | `finished` | `clipboard` |
	 *  `agent` | `subagent` | `session`.
	 */
	what: string,
	detail: string | null,
};

export type HeadsDown = {
	projectId: string,
	/**
	 *  Seconds since the epoch. `f64` because the contract forbids 64-bit
	 *  integers, and every other timestamp that crosses it is one too.
	 */
	since: number | null,
	/**
	 *  When the queue is let go, for a focus that was given a length. Absent
	 *  is a focus with no end in mind, which is the default.
	 * 
	 *  Reaching it does not end the focus and does not open a dialog: the door
	 *  opens, the pill says so, and the person leaves when they are ready.
	 */
	until: number | null,
};

/**  One thing the workspace holds, measured. */
export type Held = {
	name: string,
	path: string,
	/**  Bytes, measured now. */
	bytes: number | null,
	/**  How many things are in it, for a directory. Absent for a file. */
	count: number | null,
	isDir: boolean,
	/**
	 *  False when the workspace has not made it yet — a row that says "not
	 *  yet" is honest; a row that says 0 B is not.
	 */
	exists: boolean,
};

/**
 *  How this copy of devpit was installed, which decides what an update may do
 *  to it.
 */
export type InstallKind = 
/**  A single file the app can replace by itself. */
"appImage" | 
/**
 *  A system package: downloaded and verified here, installed by the person
 *  with the command we show. The app never runs a package manager.
 */
"deb" | 
/**
 *  A package the machine's own tooling looks after — a repackage, a Nix
 *  profile, a container. Nothing is downloaded.
 */
"externallyManaged" | 
/**
 *  `make dev`, a `cargo run`, or anything else with no bundle around it.
 *  Nothing is installed from here.
 */
"unmanaged";

/**  One installation, as the panels offer it. */
export type Installation = {
	directory: string,
	/**
	 *  The profiles that run against it. Empty for the one this process would
	 *  use with no profile at all.
	 */
	profiles: string[],
	/**  The same profiles by id, which a label is not: two can share a name. */
	ids?: string[],
	/**  Whether the default profile runs against it — where the panels start. */
	default: boolean,
};

/**
 *  What a session is keeping, so emptying it can say so before it happens.
 * 
 *  Not `Held`: `workspace.rs` already exports one, and two types with one name
 *  is a contract that will not generate.
 */
export type Kept = {
	session: string,
	/**
	 *  How many bytes the session's directory takes. `f64` rather than `u64`:
	 *  specta refuses a type that could lose precision crossing into
	 *  JavaScript, and a browser session is not measured in exabytes.
	 */
	bytes: number | null,
	/**  Whether anything is there at all. */
	used: boolean,
};

/**
 *  One agent CLI this build can start, for `agents.known`.
 * 
 *  The same list that recognises a running one. They cannot be two lists: a
 *  menu that starts Gemini and a sidebar that then calls the pane `node` is
 *  the shape of the bug this replaces.
 */
export type KnownAgent = {
	/**  Stable, and what the screen keys an icon by. */
	id: string,
	label: string,
	/**  What gets typed into the terminal to start it. */
	launch: string,
	/**
	 *  Whether it is on this machine's PATH. A menu still lists the others —
	 *  saying what could be installed is more use than a short list with no
	 *  explanation.
	 */
	installed: boolean,
	/**
	 *  Whether it is offered at all. A person with twelve agents on the list
	 *  uses two, and a menu that offers all twelve is a menu they read past.
	 */
	enabled?: boolean,
	/**
	 *  Where its own documentation lives. Empty for a profile, which is
	 *  somebody's own and has no page to send them to.
	 */
	homepage?: string,
};

/**  An app this build knows how to offer before anyone has typed anything. */
export type KnownApp = {
	id: string,
	label: string,
	command: string,
};

export type LayoutNode = { type: "leaf"; id: string; 
/**  `session:window` on our private tmux server. */
tmuxTarget: string; kind: PaneKind; agent: AgentPresence; 
/**
 *  The name the person gave this pane, or empty when they have not.
 * 
 *  Empty rather than absent so the screen has one field to read: a
 *  pane titled by an OSC sequence is showing what the program called
 *  itself, and a pane titled here is showing what its owner called it.
 *  The second always wins, and only a rename clears or sets it.
 */
title?: string } | { type: "split"; 
/**
 *  What a dragged boundary is addressed by.
 * 
 *  Defaulted rather than migrated: a tree persisted before splits had
 *  ids loads with this empty, and [`LayoutNode::name_the_splits`]
 *  fills it on the first read. A migration would have to rewrite every
 *  stored tree to add a field nothing had asked for yet.
 */
id?: string; direction: SplitDirection; ratio: number | null; first: LayoutNode; second: LayoutNode };

/**
 *  What the account pane draws.
 * 
 *  `account` is null for "nobody is signed in", which is a state and not an
 *  error — a screen that has to catch a failure to draw its signed-out half
 *  draws it late.
 */
export type Membership = {
	account: Account | null,
	/**
	 *  Where the browser is sent, so the screen can name it without hard-coding
	 *  a domain the build might not be pointing at.
	 */
	origin: string,
	/**
	 *  False when the token on disk was refused. The person is signed out, and
	 *  telling them it expired is kinder than pretending they never signed in.
	 */
	expired: boolean,
};

/**
 *  What the menu is being opened for, sent to it the moment it is shown.
 * 
 *  Everything it needs to draw itself correctly on the first frame. A menu
 *  that opened and *then* asked which session was current would show the wrong
 *  tick for as long as the round trip took, and the tick is the one thing
 *  somebody opens this to check.
 */
export type MenuFor = {
	pane: string,
	/**
	 *  Where the pane's page is, which is the site the import offers to narrow
	 *  to. Empty for a pane with nothing open.
	 */
	at: string,
	session: string,
	/**  The page-width preset's id, or none for the whole pane. */
	viewport: string | null,
	granted: boolean,
};

export type Message = {
	id: string,
	turnId: string | null,
	role: Role,
	parts: Part[],
	/**  Unix seconds. */
	createdAt: number | null,
	/**  True while more of it is still arriving. */
	streaming: boolean,
};

/**  Something worth telling somebody about. */
export type Notice = {
	id: string,
	projectId: string | null,
	/**
	 *  `run`, `agent`, `due`, `irreversible`. A word rather than an enum
	 *  because the set grows with whatever learns to notice something, and a
	 *  kind this build does not know should draw as a plain row, not fail.
	 */
	kind: string,
	title: string,
	detail: string | null,
	/**  Where clicking it goes. Null for a notice with nowhere to go. */
	cardId: string | null,
	createdAt: number | null,
	readAt: number | null,
};

/**
 *  Response of every notice command.
 * 
 *  The count comes with the list so the bell and the list can never disagree —
 *  two reads a second apart is exactly how a badge ends up saying 3 over an
 *  empty panel.
 */
export type Notices = {
	notices: Notice[],
	unread: number,
};

/**  One app in the list. */
export type OpenApp = {
	/**  Stable, and what the menu is keyed on. */
	id: string,
	label: string,
	/**  The program, as it would be typed into a terminal. One word. */
	command: string,
	/**
	 *  Whether this machine can actually run it. Asked of the shell, not of
	 *  `PATH`: an editor launched by a shell function has no file on `PATH`
	 *  and would be greyed out for no reason.
	 */
	installed: boolean,
};

export type Opened = {
	/**
	 *  What was handed over, resolved. The screen shows it when opening fails
	 *  so the person can go there themselves.
	 */
	path: string,
};

/**
 *  A session of this project the CLI holds and devpit never saw — one started
 *  in a terminal.
 */
export type OutsideSession = {
	sessionId: string,
	/**  The CLI's own title, when it wrote one. */
	title: string | null,
	/**  The configuration directory of the installation that holds it. */
	installation: string,
	/**  Unix seconds. */
	lastAt: number | null,
};

/**  A pane's blocks, and where its shell stands. */
export type PaneBlocks = {
	/**  Oldest first; the one still running, if any, last. */
	blocks: CommandBlock[],
	/**
	 *  The shell has been heard marking its prompts since the app started, so
	 *  its commands can be drawn as blocks.
	 */
	integrated: boolean,
	/**  It is at its prompt, waiting for a line. */
	atPrompt: boolean,
	/**  The folder it last said it was in. */
	cwd: string | null,
};

/**  One pane, and the whole process tree under it. */
export type PaneCost = {
	paneId: string,
	/**  The agent's name when it is one, the executable's otherwise. */
	label: string,
	agent: string | null,
	/**
	 *  Kibibytes, proportional where the kernel would say — see `proportional`.
	 * 
	 *  32 bits because the contract crosses into JavaScript, which holds
	 *  integers exactly only to 2^53 — so specta refuses a `u64` outright
	 *  rather than letting a number arrive quietly wrong. Four tebibytes is
	 *  past anything a terminal will hold.
	 */
	memoryKb: number,
	/**
	 *  Tenths of a percent, since the last time this was asked. Zero for a
	 *  pane asked about once: a rate from one sample is not a rate.
	 * 
	 *  Tenths and not a float, because specta types an `f64` as `number |
	 *  null` — a float can be NaN, which JSON has no word for. An integer
	 *  crosses the wire meaning exactly what it says, and the rounding
	 *  happens once, here, rather than in Rust and again in TypeScript.
	 */
	cpuTenths: number,
	/**
	 *  How many processes the tree holds. An agent with fifteen is worth
	 *  knowing about even when the memory looks ordinary.
	 */
	processes: number,
};

/**  What a leaf shows. Only `terminal` in this slice. */
export type PaneKind = "terminal";

/**
 *  What is running in one pane, for `session.running`.
 * 
 *  The foreground process, asked of the operating system rather than reported
 *  by the program itself: an agent CLI opened in a terminal has no reason to
 *  tell this app it exists, and the sidebar still has to know.
 */
export type PaneRunning = {
	paneId: string,
	/**
	 *  The command's own name: `zsh`, `claude`, `codex`, `cargo`.
	 * 
	 *  Read from the arguments, not from the executable: every agent CLI
	 *  written in JavaScript runs as `node`, and a row saying `node` names
	 *  nothing anyone recognises.
	 */
	command: string,
	/**  False while the shell itself is in front, which is nothing running. */
	busy: boolean,
	/**
	 *  Which agent this is, when it is one. `null` for a shell, a build, an
	 *  editor — anything the app has no particular name for.
	 */
	agent: string | null,
	/**
	 *  What to call it on screen: `Claude Code` for an agent, and the
	 *  command's own name for everything else.
	 */
	label: string,
};

/**  Response of `pane.scrollback`. */
export type PaneScrollback = {
	text: string,
	/**  Older output has been dropped to make room. */
	truncated: boolean,
};

/**
 *  Response of `pane.resize`.
 * 
 *  The size that ended up applied, which is not always the size asked for: a
 *  pty clamps, and a pane that believes it has two hundred columns when it has
 *  eighty draws wrongly a long way from the line that caused it.
 */
export type PaneSize = {
	rows: number,
	cols: number,
};

/**  Response of `session.write`. */
export type PaneWritten = {
	bytes: number,
};

/**
 *  One piece of a message.
 * 
 *  `parent` names the `Agent` call a subagent's part came from. Empty for the
 *  agent's own work. Defaulted so a transcript written before it existed still
 *  reads.
 */
export type Part = { kind: "text"; text: string; parent?: string | null } | 
/**  Reasoning the model showed. Separate because it is not the answer. */
{ kind: "thinking"; text: string; parent?: string | null } | { kind: "tool_call"; id: string; name: string; 
/**
 *  Verbatim. Parsing it here would be this crate guessing at a shape
 *  the provider is free to change.
 */
input: string; state: CallState; parent?: string | null } | { kind: "tool_result"; 
/**  The call this answers. */
call_id: string; output: string; is_error: boolean; parent?: string | null } | 
/**
 *  Work the CLI runs beside the conversation: a backgrounded subagent or
 *  command. One part per change, so the latest for a `task_id` is its state.
 */
{ kind: "task"; task_id: string; 
/**  The tool call that started it, when the CLI says. */
call_id: string | null; 
/**  The CLI's own word: `local_agent`, `local_bash`. */
task_kind: string | null; description: string | null; 
/**  `started`, `running`, then the CLI's own ending (`completed`, …). */
status: string; summary: string | null } | 
/**  What a slash command itself answered, as the CLI printed it. */
{ kind: "command"; content: string } | 
/**  A permission question somebody answered, kept in the thread. */
{ kind: "receipt"; tool: string; 
/**  The tool's input as the question showed it. */
input: string; allowed: boolean } | 
/**  What the turn changed in the checkout, measured before and after it. */
{ kind: "changes"; files: ChangedFile[] } | 
/**
 *  This conversation was forked from another at one of its turns, which
 *  left that one as it was.
 */
{ kind: "rewound"; from_conversation: string; turn: number } | 
/**
 *  A line the driver did not recognise. Kept rather than dropped: losing
 *  output is worse than showing it plain.
 */
{ kind: "unknown"; text: string };

/**
 *  What a plugin is allowed to do beyond drawing its own surfaces.
 * 
 *  A closed set on purpose: a plugin compiled into the app is trusted with
 *  exactly what this enum names, never with whatever it asks for.
 */
export type Permission = 
/**  Owns the files under its own data folder — nothing outside it. */
"dataOwn";

/**
 *  A file pinned to a card.
 * 
 *  `Pinned` and not `Attachment` because `chat::Attachment` already means
 *  something else — a file handed to an agent for one turn. This one outlives
 *  the turn and belongs to the card.
 */
export type Pinned = {
	id: string,
	/**  Absolute, and local only. */
	path: string,
	label: string,
	/**
	 *  False when the file has since been moved or deleted. Drawn as missing
	 *  rather than dropped: a pin that vanishes takes the memory of it too.
	 */
	exists: boolean,
	/**  Bytes, when it could be read. */
	bytes: number | null,
	createdAt: number | null,
	/**
	 *  The plugin that pinned it. The screen opens the pin there while that
	 *  plugin is on, and as a plain file otherwise.
	 */
	plugin: string | null,
};

/**
 *  A folder worth a shortcut.
 * 
 *  Every folder devpit makes for a project is named by ULID, so the way to
 *  this project's own files is thirty characters nobody can recognise, let
 *  alone type.
 */
export type Place = {
	label: string,
	path: string,
};

/**  Response of `plan.limits`. */
export type PlanLimits = {
	installation: string,
	plan: string | null,
	windows: PlanWindow[],
	/**  Unix seconds. */
	readAt: number | null,
	/**  Why there are no windows, said rather than drawn as zero. */
	problem: string | null,
};

/**  One quota window of a plan. */
export type PlanWindow = {
	label: string,
	/**  0 to 100. */
	percent: number | null,
	/**  Unix seconds. */
	resetsAt: number | null,
};

/**
 *  What pressing play did, or why it did not.
 * 
 *  Three answers rather than an error for two of them: a lane that runs
 *  nothing and a step that wants confirming are both ordinary, and the screen
 *  says something different for each.
 */
export type Played = {
	/**  The run that started, when one did. */
	run: Run | null,
	/**  The lane's step has no undo and nobody has said to run it. */
	needsConfirming: boolean,
	/**  This lane runs nothing, so there was nothing to play. */
	laneRunsNothing: boolean,
};

/**  One file in a plugin's data folder. */
export type PluginFile = {
	/**  With its extension, e.g. `flow.excalidraw`. */
	name: string,
	bytes: number | null,
	/**  Milliseconds since the epoch. */
	modified: number | null,
};

/**  Response of `plugin.data.delete`. `false` when there was nothing to remove. */
export type PluginFileRemoved = {
	removed: boolean,
};

/**  Response of `plugin.data.write`. */
export type PluginFileSaved = {
	name: string,
	modified: number | null,
};

/**  Response of `plugin.data.read`. */
export type PluginFileText = {
	name: string,
	text: string,
	/**  Given back on write, so a save can refuse a change it never saw. */
	modified: number | null,
};

/**  Response of `plugin.data.list`. */
export type PluginFiles = {
	files: PluginFile[],
};

/**
 *  Response of `plugin.list`, `plugin.install` and `plugin.set_enabled`: the
 *  whole catalogue.
 */
export type PluginList = {
	plugins: PluginState[],
};

/**  What one plugin declares about itself. */
export type PluginManifest = {
	/**  Stable, and the name of its data folder. Checked by [`validate`]. */
	id: string,
	name: string,
	version: string,
	description: string,
	surfaces: Surface[],
	data: DataSpec,
	permissions: Permission[],
};

/**
 *  One plugin of the catalogue, whether this project installed it, and
 *  whether it is on.
 */
export type PluginState = {
	manifest: PluginManifest,
	/**  Only an installed plugin can be on. */
	installed: boolean,
	enabled: boolean,
};

/**
 *  Response of `plugin.uninstall`: the catalogue as it is now, under the same
 *  field as [`PluginList`], and how many of the plugin's files were deleted.
 */
export type PluginUninstalled = {
	plugins: PluginState[],
	/**  0 when the files were kept. */
	removedFiles: number,
};

export type Profile = {
	id: string,
	/**  What the person calls this account. */
	label: string,
	/**  The binary to run. Two accounts differ here and nowhere else. */
	command: string,
	/**  Which driver reads its output. */
	driver: string,
	/**
	 *  Where the command resolves to, when it resolves to a file at all.
	 *  Set exactly when `reach` is `Runnable`.
	 */
	path: string | null,
	/**  How far this machine gets with `command`. */
	reach: Reach,
	/**
	 *  The agent this behaves like. Empty for a discovered command, which is
	 *  only ever itself.
	 */
	base?: string,
	args?: string[],
	env?: EnvVar[],
	/**
	 *  Whether the person declared this one, and may therefore rename, edit or
	 *  delete it. A discovered command is devpit noticing, not a choice.
	 */
	mine?: boolean,
	/**
	 *  The models the composer may pick from: the profile's own when it
	 *  named some, the driver's otherwise. Carried here so one call answers
	 *  the whole selector.
	 */
	models?: string[],
	/**
	 *  The models the person listed, as written — what the editor opens with.
	 *  Kept apart from `models`, which a save would otherwise make theirs.
	 */
	ownModels?: string[],
	/**
	 *  How hard the agent may be asked to think. Empty when the CLI has no
	 *  such control, and the composer then draws no chip at all.
	 */
	efforts?: string[],
	effortDefault?: string | null,
};

/**
 *  A project as the window needs it.
 * 
 *  The worktrees come with it because the row that names a project is the row
 *  that reports its branch and its dirt — fetching those separately would draw
 *  the list once and then correct it.
 */
export type Project = {
	id: string,
	name: string,
	/**  Local only. An absolute path means nothing on another machine. */
	rootPath: string,
	/**  Optional heading in the list. */
	group: string | null,
	/**
	 *  Persistent and mandatory, from the trust workspace: it is what keeps
	 *  one client's context from being read as another's.
	 */
	accent: string,
	worktrees: Worktree[],
	/**
	 *  Why the repository could not be read, when it could not be. Present and
	 *  non-null is the only honest way to draw a project whose git is missing.
	 */
	unreadable: string | null,
	/**
	 *  `remote.origin.url`, read when the project was registered. What tells
	 *  two checkouts of one repository apart from two unrelated folders.
	 */
	origin: string | null,
	/**
	 *  Seconds since the epoch; see `Commit::committed_at` for why `f64`.
	 *  Absent for a project registered and never opened.
	 */
	lastOpenedAt: number | null,
	/**
	 *  The icon a person chose: `icon:<name>` from the app's own set, or an
	 *  emoji. Absent until somebody chooses; the rail then draws initials.
	 */
	icon: string | null,
	/**  The colour chosen with it, as `#rrggbb`. */
	color: string | null,
};

export type ProjectChanges = {
	changes: Change[],
	/**
	 *  Totals come from the server so the screen never adds up a list it may
	 *  have truncated.
	 */
	added: number,
	removed: number,
};

export type ProjectHistory = {
	commits: Commit[],
	/**
	 *  Whether git has more commits than this page carries — what the screen
	 *  reads to decide whether "load older" still does anything.
	 */
	hasMore: boolean,
};

export type ProjectList = {
	projects: Project[],
};

export type ProjectRun = {
	run: Run,
	cardId: string,
	cardTitle: string,
};

export type ProjectTree = {
	nodes: FileNode[],
};

/**  What the agent wants to do, as the screen puts it. */
export type Question = {
	/**  This question, so the answer can name it. */
	id: string,
	/**  The CLI's session, which is what ties it to a conversation. */
	sessionId: string,
	tool: string,
	/**
	 *  The tool's input, verbatim. Parsing it here would be guessing at a
	 *  shape the provider changes without asking.
	 */
	input: string,
	cwd: string,
};

/**
 *  How far this machine can get with a command.
 * 
 *  Three answers and not two, because "installed" is not a yes or a no here.
 *  On the machine this was written on `claude` is a **shell function** in
 *  `.zshrc` with no file anywhere on `PATH`: a terminal starts it, because a
 *  terminal types into that shell, and `Command::new` cannot — you cannot exec
 *  a function. A single boolean has to pick one of those to be wrong about.
 */
export type Reach = 
/**
 *  An executable file on the `PATH`. Works everywhere: terminal, chat and
 *  the board's headless turns.
 */
"runnable" | 
/**
 *  The person's shell knows the name but no file answers to it — a
 *  function or an alias. The terminal can start it and nothing else can.
 */
"shell_only" | 
/**  Neither. Nothing here can start it. */
"missing";

/**
 *  A command of the person's own — a shell function such as `claudin` —
 *  read by running it: the agent it starts, and what it starts it with.
 */
export type ReadCommand = {
	/**  The agent it runs, by `devpit_pty::agents` id. */
	base: string,
	args: string[],
	env: EnvVar[],
};

export type RejectedAgent = {
	file: string,
	reason: string,
};

/**  What removing a worktree would cost, when it refuses. */
export type Removed = {
	uncommittedFiles: number,
	uncommittedLines: number,
	/**
	 *  The branch that stayed behind. The folder is disposable; the commits
	 *  in it are not.
	 */
	branchKept: string | null,
};

/**  Who said it. */
export type Role = "user" | "assistant" | "system";

export type RpcError = {
	code: ErrorCode,
	message: string,
	retryAfterMs: number | null,
	details: string | null,
};

/**
 *  One execution of a step, and what it cost.
 * 
 *  The cost is on the record rather than derived later: "the agent is doing
 *  something" stops being an acceptable answer once the card can say what it
 *  spent.
 */
export type Run = {
	id: string,
	stepId: string,
	stepName: string,
	state: RunState,
	output: string | null,
	exitCode: number | null,
	costUsd: number | null,
	/**
	 *  `f64` and not `i64` throughout, because this crosses into a JavaScript
	 *  number and that is what a JavaScript number is — see
	 *  `Commit::committed_at` for the same reason stated once.
	 */
	durationMs: number | null,
	startedAt: number | null,
};

/**  Where the last page ended: the next one starts after this run. */
export type RunCursor = {
	startedAt: number | null,
	id: string,
};

/**  How a run ended, or that it has not. */
export type RunState = "running" | "ok" | "failed" | "cancelled" | "lost";

export type RunsPage = {
	runs: ProjectRun[],
	/**  Absent on the last page. */
	next: RunCursor | null,
};

/**  What to list. Every filter is optional, and they narrow together. */
export type RunsQuery = {
	projectId: string,
	/**  A lane is filtered by the step it runs. */
	stepId: string | null,
	state: RunState | null,
	/**  Unix seconds, inclusive. */
	since: number | null,
	/**  Unix seconds, exclusive. */
	until: number | null,
	after: RunCursor | null,
};

export type SearchFile = {
	path: string,
	lines: SearchLine[],
};

export type SearchHits = {
	files: SearchFile[],
	/**
	 *  How many lines matched, before the ceiling cut `files` short. The true
	 *  size, even on a call where `files` cannot carry all of it. Named
	 *  `matched` rather than `shown`: `shown` is what a screen renders after
	 *  its own cap, the way `SearchResults.tsx` already uses the word for the
	 *  slice of `hits` it draws — this is the number before either cap.
	 */
	matched: number,
	/**  True once `matched` is more than what `files` actually holds. */
	truncated: boolean,
};

export type SearchLine = {
	line: number,
	text: string,
};

export type Server = {
	name: string,
	/**  `project` or `user` — which file names it. */
	scope: string,
	/**  The command or URL it is reached by, for the row's second line. */
	reachedBy: string,
};

export type Servers = {
	servers: Server[],
	/**
	 *  The files this was read from, so the panel can say whose catalogue it
	 *  is showing.
	 */
	sources: string[],
	/**
	 *  Why nothing could be read. A panel that says why beats a panel that
	 *  looks empty.
	 */
	problem: string | null,
	/**  The command that manages them, to copy. Never run from here. */
	manageWith: string,
	/**  The CLI configuration directory these came from. */
	directory: string,
};

export type SessionHit = {
	sessionId: string,
	/**  `user` or `assistant`. */
	role: string,
	/**  The words around the match, the matched ones between `[` and `]`. */
	snippet: string,
	/**  The installation whose transcript it is. */
	installation: string,
	/**
	 *  The devpit conversation that already resumes this session, if one does —
	 *  so a hit opens that tab instead of taking the session in a second time.
	 */
	conversationId: string | null,
};

/**  Where a session working on a card lives. */
export type SessionKind = "pane" | "run" | "background" | "chat";

/**  Response of `session.layout` / `session.ensure` / `session.split`. */
export type SessionLayout = {
	projectId: string,
	focusedId: string,
	tree: LayoutNode,
};

export type Settings = {
	theme: Theme,
	/**  Unix seconds, or null while the first run has not been finished. */
	onboardedAt: number | null,
	/**
	 *  Three states, not two: `null` is "never asked", which is what lets a
	 *  default be a default rather than a silent choice. Updates are on when
	 *  the person has not said otherwise.
	 */
	automaticUpdates: boolean | null,
	/**
	 *  Whether closing a terminal with an agent or a command still running
	 *  stops to ask first.
	 * 
	 *  Null is "never asked", and never-asked means yes: the first time
	 *  someone closes a tab with work in it, the prompt is the only thing
	 *  standing between them and losing it. It goes to `false` when they tick
	 *  "don't ask again", which is a choice and not a default.
	 */
	confirmStop: boolean | null,
	/**
	 *  The contrast xterm lifts every colour to, from 1 (none) to 21. Null is
	 *  "never asked", which keeps the old rule: none on the dark ground, 4.5
	 *  on the light one.
	 */
	terminalContrast: number | null,
	/**
	 *  Whether the focus mode is offered at all.
	 * 
	 *  Off unless somebody turns it on, and `null` is off here rather than
	 *  "never asked": an unfinished thing does not get to be the default by
	 *  virtue of nobody having had an opinion about it yet.
	 */
	focusMode: boolean | null,
	/**
	 *  Whether devpit keeps its own errors for an anonymous report.
	 * 
	 *  Opt-in: `null` is off. Turning it off deletes what was kept.
	 */
	errorReports: boolean | null,
};

/**
 *  How much a finding is claimed to matter.
 * 
 *  A closed set, and small. Seven levels is a scale nobody agrees on twice,
 *  and a review's job is to be acted on rather than scored.
 */
export type Severity = 
/**  Would break something if it shipped. */
"blocking" | 
/**  Worth fixing, not worth stopping for. */
"worth" | 
/**  Said for the record. */
"noted";

/**
 *  What a page is doing, told to the window as it happens.
 * 
 *  A webview does not report its address back, and remembering the last url
 *  devpit asked for is not the same thing: a link, a redirect or a form leaves
 *  the bar saying where the page *was* sent rather than where it *is*. So the
 *  real one is read on every load and sent over.
 */
export type Showing = {
	/**  The pane whose page this is. */
	pane: string,
	/**  Where the page actually is, as the webview reports it. */
	url: string,
	/**
	 *  What the page calls itself, once it has finished loading and has had
	 *  the chance to set one. Empty while it is still arriving, and empty for
	 *  a page that names itself nothing — a tab then falls back to the url,
	 *  which is what a browser has always done.
	 */
	title: string,
};

/**  A sign-in that has started but not finished. */
export type SignIn = {
	/**
	 *  Shown in the app, and already in the url the browser opened. Typing it
	 *  is the fallback, not the path.
	 */
	userCode: string,
	verifyUrl: string,
	expiresInSeconds: number,
	/**
	 *  How often the app may ask. The server decides, so a polling loop cannot
	 *  become a load test by being written badly here.
	 */
	intervalSeconds: number,
};

/**  Where a sign-in stands, each time the screen asks. */
export type SignInState = 
/**  Nobody has approved it yet. Ask again after `interval_seconds`. */
{ state: "waiting" } | 
/**  Done. The token is already on disk; the screen gets the person. */
{ state: "signed"; account: Account } | 
/**  The code ran out, or was already used. Start again. */
{ state: "expired" };

export type Skill = {
	name: string,
	/**  Where it came from — `omc`, `claude`, `yours`. */
	source: string,
	/**  The `SKILL.md` itself, so Open and Reveal have something to hand over. */
	path: string,
	/**  The author's own one line, from the frontmatter. */
	description: string,
};

/**  One skill, with the whole of its `SKILL.md`. */
export type SkillDoc = {
	name: string,
	path: string,
	/**  The file as written, Markdown and all, with the frontmatter removed. */
	body: string,
};

export type Skills = {
	skills: Skill[],
	/**
	 *  Why nothing could be read, when nothing could. Present and non-empty
	 *  means the panel says this instead of looking empty.
	 */
	problem: string | null,
	/**
	 *  The CLI configuration directory these came from.
	 * 
	 *  On screen because it is not always `~/.claude`, and a panel listing
	 *  another installation's skills is indistinguishable from a panel
	 *  listing this one's — see `cli_config`.
	 */
	directory: string,
};

/**  One kind of checkout, with the count that makes the choice meaningful. */
export type Source = {
	/**  `devpit`, `claude`, `other` — what the preference stores. */
	id: string,
	label: string,
	/**  Where these sit, in the shape a person would recognise. */
	hint: string,
	/**
	 *  How many this project has right now. Hiding a kind it has none of is a
	 *  switch that does nothing, and the count is what says so.
	 */
	count: number,
	shown: boolean,
};

/**  What a project has actually spent. */
export type Spend = {
	usd: number | null,
	/**
	 *  How many runs reported a cost. Zero means nothing has been measured,
	 *  which the screen says rather than drawing a zero.
	 */
	runs: number,
	/**  Title and cost, most expensive first. */
	cards: ([string, number | null])[],
};

/**  A card a session is known to belong to. */
export type SpendCard = {
	id: string,
	title: string,
};

/**  One UTC day. */
export type SpendDay = {
	/**  `YYYY-MM-DD`, UTC. */
	day: string,
	costUsd: number | null,
	tokens: TokenCounts,
	/**  Cost by model, most first. */
	byModel: SpendShare[],
};

/**  Response of `spend.history`. */
export type SpendHistory = {
	days: number,
	installations: SpendInstallation[],
	costUsd: number | null,
	tokens: TokenCounts,
	sessions: number,
	turns: number,
	activeDays: number,
	/**  The share of input served from the cache, 0 to 1. */
	cacheReuse: number | null,
	daily: SpendDay[],
	models: SpendRow[],
	projects: SpendRow[],
	/**  Most recently active first, at most twenty. */
	recent: SpendSession[],
	/**  Some of the dollars are list price for an installation not billed by Anthropic. */
	estimated: boolean,
	/**  Tokens from models the price table does not know. */
	unpricedTokens: number | null,
	files: number,
	records: number,
	scanMs: number | null,
};

/**  An agent CLI installation the history reads from. */
export type SpendInstallation = {
	directory: string,
	label: string,
	/**
	 *  False for an installation pointed at another provider: its dollars are
	 *  Anthropic's list price for tokens nobody billed that way.
	 */
	billed: boolean,
};

/**  A model or a project, over the whole range. */
export type SpendRow = {
	name: string,
	costUsd: number | null,
	tokens: TokenCounts,
	sessions: number,
	/**  Unix seconds. */
	lastActive: number | null,
};

export type SpendSession = {
	sessionId: string,
	project: string,
	/**  The model that wrote most of its tokens. */
	model: string,
	turns: number,
	tokens: TokenCounts,
	costUsd: number | null,
	/**  Unix seconds. */
	lastActive: number | null,
	installation: string,
	card: SpendCard | null,
};

export type SpendShare = {
	name: string,
	costUsd: number | null,
	tokens: number | null,
};

/**  Orca's names: horizontal is left/right, vertical is top/bottom. */
export type SplitDirection = "horizontal" | "vertical";

/**  Whether a finding is still about the code in front of you. */
export type Standing = 
/**  Made against the revision that is checked out. */
"current" | 
/**
 *  Made against another. The line number is not re-pointed, and the
 *  screen says which revision it meant.
 */
"outdated" | 
/**  Nothing recorded which revision it was made against. */
"unanchored";

export type Step = {
	id: string,
	kind: StepKind,
	name: string,
	/**
	 *  Shaped by `kind`. Opaque here on purpose: the contract would otherwise
	 *  have to grow a variant every time a step learns an option.
	 */
	config: string,
	/**  A deploy has no undo, so it is confirmed rather than fired by a drag. */
	irreversible: boolean,
};

/**
 *  What a column runs when a card arrives in it.
 * 
 *  Three kinds because they behave in opposite ways, and the difference is
 *  visible on screen: only `Session` takes the terminal.
 */
export type StepKind = 
/**  One headless turn. Returns schema-validated JSON, takes no terminal. */
"agent" | 
/**  A session you drive. This one takes the target terminal. */
"session" | 
/**  A command of yours: tests, a build, a deploy. */
"command";

/**  A cookie store on this machine that a pane could be given. */
export type Store = {
	/**  The browser: `Google Chrome`, `Firefox`, `Safari`. */
	family: string,
	/**
	 *  The profile inside it: `Default`, `Profile 1`. Empty for a browser that
	 *  keeps one jar, which is how a menu knows not to ask a second question.
	 */
	profile: string,
	/**  Where it is, which is also how a caller names it back. */
	path: string,
	/**
	 *  Whether reading it needs a key from the desktop keyring, and whether
	 *  this machine can ask for one. Empty when nothing stands in the way.
	 */
	warning: string,
};

/**
 *  One capability of the desktop UI a plugin can occupy.
 * 
 *  Tagged the way [`crate::session::LayoutNode`] is: `Pane` carries data,
 *  `CardPin` does not, and one enum says both.
 */
export type Surface = 
/**
 *  A pane in the workspace strip. `many` says whether a project may have
 *  more than one open at once.
 */
{ type: "pane"; many: boolean } | 
/**  A pin shown on the card face. */
{ type: "cardPin" };

/**  What an import actually did. */
export type Taken = {
	/**  Which store it came from. */
	family: string,
	/**
	 *  How many cookies moved. `u32` rather than `usize`: specta refuses to
	 *  export a type that could lose precision crossing into JavaScript, and a
	 *  count that needs more than four billion is not a cookie store.
	 */
	count: number,
	/**  Which domains they were for, in the order they were asked for. */
	domains: string[],
};

/**
 *  The appearance the window uses.
 * 
 *  An enum and not a string, so a build that does not ship a theme cannot be
 *  asked for one. `System` is a third setting, not a third palette: it borrows
 *  whichever of the two the machine is already using.
 */
export type Theme = "system" | "light" | "dark";

/**
 *  One conversation, as a row in a list.
 * 
 *  A summary, not a `Conversation`: that one carries every message, and a
 *  list of them would read the whole history to draw a sidebar.
 */
export type Thread = {
	id: string,
	/**
	 *  The first thing the person said. Their words, not a summary written
	 *  by a model — the row exists to be recognised.
	 */
	title: string,
	profile: string,
	model: string | null,
	costUsd: number | null,
	/**  Unix seconds, when it was last spoken in. */
	lastAt: number | null,
};

/**  Tokens by kind. */
export type TokenCounts = {
	input: number | null,
	output: number | null,
	cacheRead: number | null,
	cacheWrite: number | null,
};

/**  What a turn cost and why it stopped. */
export type TurnEnd = {
	turnId: string,
	costUsd: number | null,
	durationMs: number | null,
	/**  The CLI's own word, kept rather than flattened into "failed". */
	stopReason: string | null,
	isError: boolean,
	context: Context | null,
};

/**  One thing an update is waiting for. */
export type UpdateBlocking = {
	/**  The run or the conversation. */
	id: string,
	/**
	 *  What a person would recognise it by: the card's title, the
	 *  conversation's.
	 */
	title: string,
};

/**  Where the update is, and what may be done about it. */
export type UpdateStatus = 
/**  Nothing known, or nothing newer. */
{ type: "idle" } | { type: "checking" } | { type: "available"; version: string; notes: string; kind: InstallKind; 
/**
 *  True when the answer came from a test feed rather than the real
 *  one. The window says so: an offer nobody can install has to look
 *  different from one they can.
 * 
 *  Renamed by hand: `rename_all` on a tagged enum renames the
 *  variants, not the fields inside them.
 */
testFeed: boolean } | { type: "downloading"; percent: number } | 
/**  Downloaded and verified. From here on the app refuses to start new work. */
{ type: "ready"; version: string } | 
/**  Waiting for work that is already running, with what it is waiting on. */
{ type: "waiting"; runs: number; turns: number; 
/**  Seconds since the epoch, so the window can say how long. */
since: number | null } | 
/**  Past the point of return: the installer is running. */
{ type: "installing" } | 
/**  A package the person installs, with the command to do it. */
{ type: "manualInstall"; command: string; path: string } | { type: "externallyManaged" } | { type: "failed"; message: string; 
/**  False once the install has committed: there is nothing to retry. */
recoverable: boolean };

/**  What is running while an update waits to install. */
export type UpdateWork = {
	runs: UpdateBlocking[],
	turns: UpdateBlocking[],
	/**
	 *  Terminal agents and background sessions. Not in the way: they live in
	 *  tmux or in the CLI's own daemon, and they keep running through the
	 *  restart. Listed so the person does not have to take that on trust.
	 */
	keeps: UpdateBlocking[],
};

/**  Every pane of a project, and the total. */
export type Usage = {
	memoryKb: number,
	/**  Tenths of a percent. See `PaneCost::cpu_tenths`. */
	cpuTenths: number,
	/**
	 *  Whether shared pages were divided among the processes sharing them.
	 * 
	 *  False means at least one process could only be read as resident, and
	 *  the total is therefore an overcount — measured at 44% on one machine.
	 *  Said rather than hidden: a number that might be half wrong has to
	 *  arrive labelled.
	 */
	proportional: boolean,
	panes: PaneCost[],
};

/**  Whether a verdict is still about the code in front of the person. */
export type Validity = 
/**  The revision and the local changes are the ones the run saw. */
"current" | 
/**  The code moved under it. Not wrong — about other code. */
"stale" | 
/**
 *  Nothing recorded what the run saw, so nothing can say. Every run from
 *  before migration 017 is this.
 */
"unknown";

/**  What a run says about the thing it was checking. */
export type Verdict = 
/**  A report was read and everything in it passed. */
"passed" | 
/**  A report was read and something in it failed. */
"failed" | 
/**  The check never happened: the process never ran, or a person stopped it. */
"notRun" | 
/**
 *  It ran and left nothing that answers the question. The commonest one,
 *  and the one a screen must never draw as green.
 */
"inconclusive";

/**
 *  What a focus has been holding, a page at a time.
 * 
 *  An object rather than a bare list, and `more` rather than a total: a count
 *  would mean reading every row to say a number nobody acts on, and what the
 *  screen needs to know is whether to ask again.
 */
export type Waiting = {
	notices: Notice[],
	/**  True when the page filled, so there may be another behind it. */
	more: boolean,
};

/**  The circumstances of a run, as the screen reads them. */
export type WhatRan = {
	command: string | null,
	inDirectory: string | null,
	/**  The **names** of what devpit put in the environment, never the values. */
	declaredEnv: string[],
	baseRevision: string | null,
	headRevision: string | null,
	inAWorktree: boolean | null,
};

/**  Where a browser webview sits inside the window, in logical pixels. */
export type Where = {
	x: number | null,
	y: number | null,
	width: number | null,
	height: number | null,
};

/**  Who asked for a run and what carried it out. */
export type Whose = {
	/**
	 *  `board`, `card`, `checkpoint`, `chain`, or absent for a run that never
	 *  said — including every one from before this was recorded.
	 */
	asked: string | null,
	/**
	 *  The surface that asked, as a **reference**. The screen shows it and
	 *  never looks it up: a terminal that has closed is unavailable, and
	 *  finding another that shares its name would point at work that is not
	 *  this run's.
	 */
	askedFrom: string | null,
	/**  `process` or `agent`, or absent for a run that never said. */
	carried: string | null,
	/**  The profile an agent session ran under, as it stood then. */
	profile: string | null,
};

export type Widths = {
	sidebar: number,
	files: number,
};

export type Workspace = {
	directory: string,
	held: Held[],
	/**
	 *  Everything above, added up. Worktrees and transcripts grow without
	 *  announcing themselves.
	 */
	bytes: number | null,
};

/**  One entry in a workspace folder. */
export type WorkspaceEntry = {
	name: string,
	/**  Relative to the workspace root, `/` separated. */
	path: string,
	isDir: boolean,
	/**
	 *  Bytes, for a file. Zero for a directory: measuring one means walking
	 *  it, and a listing that walks every folder it lists reads the whole
	 *  workspace to draw one screen.
	 */
	bytes: number | null,
	/**  Milliseconds since the epoch; zero when it could not be read. */
	modified: number | null,
	/**  How many entries a directory holds. Absent for a file. */
	count: number | null,
};

export type WorkspaceListing = {
	/**  The workspace root, absolute, so the panel can say where this is. */
	root: string,
	/**  The folder listed, relative to the root. Empty at the top. */
	path: string,
	entries: WorkspaceEntry[],
	/**
	 *  Only the ones that exist: a shortcut to a folder devpit has not made
	 *  yet is a dead end dressed as a feature.
	 */
	places: Place[],
};

/**
 *  A checkout of the project.
 * 
 *  Real git worktrees, so the fields are git's own facts and nothing this
 *  product invented.
 */
export type Worktree = {
	/**  Stable across restarts: the absolute path, hashed. */
	id: string,
	/**  `main`, or a detached HEAD's short oid. */
	branch: string,
	/**  Last path segment. The whole path is a tooltip; it never fits a row. */
	folder: string,
	ahead: number,
	behind: number,
	/**
	 *  Files with uncommitted work, or `null` when git could not be read.
	 * 
	 *  Null rather than 0: the two look identical on screen and one of them is
	 *  a lie. Every count in this contract that can fail to be read is
	 *  optional for the same reason.
	 */
	dirtyFiles: number | null,
	/**  Who made it, so the lists can be about one kind at a time. */
	origin: WorktreeOrigin,
	/**  The checkout the project opens into. */
	current: boolean,
};

/**  The chosen base, and what it means for the project in front of you. */
export type WorktreeBase = {
	/**  Exactly what was typed, so the field shows it back unchanged. */
	typed: string,
	/**
	 *  Where the next worktree of this project would land. A sentence about
	 *  relative and absolute is not an answer; a path is.
	 */
	example: string,
	/**  True while nothing has been chosen and the workspace default is in use. */
	isDefault: boolean,
};

/**
 *  Who made a checkout.
 * 
 *  `git worktree list` returns every worktree of the repository, and a person
 *  working with agents has three kinds at once: the ones devpit made for its
 *  cards, the ones Claude Code made for itself, and whatever they made by
 *  hand. Counting all three as one number is what made the project row say
 *  "7 worktrees" about a repository the person had made none of.
 */
export type WorktreeOrigin = 
/**  Under the folder devpit creates card worktrees in. */
"devpit" | 
/**  Under a `.claude/worktrees` of its own. */
"claude" | 
/**  Everything else, which is mostly `git worktree add` by hand. */
"other";

export type Worktrees = {
	worktrees: CardWorktree[],
	/**  The whole set, so the screen can say it in one number. */
	diskBytes: number | null,
};

/**
 *  What running a step on a card would do, said before anybody runs it.
 * 
 *  A check is somebody else's command against your machine and your checkout.
 *  A button that says only "Run" asks for trust the screen has not earned:
 *  the same word can be `pnpm test` and can be a deploy.
 */
export type WouldRun = {
	stepId: string,
	stepName: string,
	/**  Marked as having no undo. The screen asks twice for one of these. */
	irreversible: boolean,
	/**
	 *  The command, for a step that has one. An agent or a session step has
	 *  none, and saying nothing is better than an empty line that reads like a
	 *  command that does nothing.
	 */
	command: string | null,
	/**
	 *  Where it **would** run. Absent when the checkout does not exist yet:
	 *  answering a question must not make one.
	 */
	inDirectory: string | null,
	inAWorktree: boolean,
	/**  The **names** of what devpit would declare, never the values. */
	declaredEnv: string[],
	timeoutSeconds: number | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

